syntax:
template<typename T>
struct Example {
    // Non-dependent name: Must be resolved in the first phase
    char array[::i];  // i is looked up immediately; if not in global scope, error

    // Dependent name: Resolved in the second phase
    int method() { return sizeof(T::c); }  // T::c is dependent, so lookup deferred

    // Implementation note: Compilers parse the template definition first,
    // checking non-dependent names against the current translation unit.
};
